        for u, v in edges:
            succ.setdefault(u, []).append(v)
        tree_paths = {src: [src]}
        queue = [src]
        while queue:
            u = queue.pop(0)
            for w in succ.get(u, []):
                if w not in tree_paths:
                    tree_paths[w] = tree_paths[u] + [w]
